const { chromium } = require('playwright');
const base='http://127.0.0.1:8787';
const gif='data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==';
const assert=(value,message)=>{if(!value)throw new Error(message);};
const checkpoint=message=>console.log(`CHECKPOINT: ${message}`);
async function api(request,method,path,data){const response=await request.fetch(`${base}${path}`,{method,headers:data===undefined?undefined:{'Content-Type':'application/json'},data});const payload=await response.json().catch(()=>({}));if(response.status()<200||response.status()>=300)throw new Error(`${method} ${path} failed (${response.status()}): ${payload.message||JSON.stringify(payload)}`);return payload;}
function options(payload){return{relationships:payload.relationshipOptions||payload.relationships||payload.options?.relationships||[],intentions:payload.intentionOptions||payload.intentions||payload.options?.intentions||[]};}
async function create(browser,suffix,selection=null,owner=false){const context=await browser.newContext({viewport:{width:1440,height:900}});const username=`postfix_${suffix}`,password=`Postfix-${suffix}-Pass-2026!`;const signup=await context.request.post(`${base}/api/auth/signup`,{data:{username,displayName:`Postfix ${suffix}`,email:`${username}@example.test`,password,rememberMe:false}});assert(signup.status()===201,`Signup ${suffix} failed.`);const onboarding=await api(context.request,'GET','/api/onboarding'),available=options(onboarding);const relationshipId=selection?.relationshipId||available.relationships[0].id,intentionIds=selection?.intentionIds||available.intentions.slice(0,2).map(item=>item.id);await api(context.request,'POST','/api/onboarding/relationship',{relationshipId});await api(context.request,'POST','/api/onboarding/intentions',{intentionIds});if(owner)await api(context.request,'POST','/api/bootstrap/owner',{password});const session=await api(context.request,'GET','/api/auth/session');return{context,id:session.user.id,username,selection:{relationshipId,intentionIds}};}
(async()=>{const browser=await chromium.launch({headless:true});let owner,visitor;const errors=[];try{owner=await create(browser,'owner',null,true);visitor=await create(browser,'visitor',owner.selection,false);const ownerPages=await api(owner.context.request,'GET','/api/experience/dashboard/pages'),visitorPages=await api(visitor.context.request,'GET','/api/experience/dashboard/pages');const group=ownerPages.groups.find(item=>visitorPages.groups.some(other=>other.id===item.id));assert(group,'No shared group.');checkpoint('accounts and shared group');
await api(owner.context.request,'POST','/api/platform/items',{type:'project',title:'Post-fix platform project',body:'Functional profile module',visibility:'account',data:{status:'active',progress:85}});await api(owner.context.request,'POST','/api/platform/items',{type:'media',title:'Post-fix media',body:'GIF module',visibility:'account',data:{mediaUrl:gif,alt:'Post-fix GIF',category:'test'}});await api(owner.context.request,'POST','/api/platform/items',{type:'task',title:'Post-fix task',body:'Dashboard module',visibility:'private',data:{priority:'high',progress:50}});const created=await api(owner.context.request,'POST','/api/experience/dashboard/pages',{name:'Post-fix shared page',scope:'group',groupId:group.id,layout:{tiles:[{featureId:'feature-chat-groups',x:0,y:0,width:3,height:2}],preferences:{density:'comfortable',tileGap:12,outerMargin:0,showDescriptions:true}}});const groupPage=created.pages.find(page=>page.name==='Post-fix shared page');await api(owner.context.request,'PUT',`/api/dashboard/collaborators/${groupPage.id}`,{collaborators:[{userId:visitor.id,permission:'manage'}]});const search=await api(owner.context.request,'GET',`/api/platform/users?q=${visitor.username}`);assert(search.users.some(user=>user.id===visitor.id),'Collaborator search failed.');checkpoint('content modules and collaboration API');
const rooms=await api(owner.context.request,'GET','/api/chat/rooms'),visitorRoomsAfter=await api(visitor.context.request,'GET','/api/chat/rooms');const groupRoom=rooms.rooms.find(room=>room.type==='group'&&visitorRoomsAfter.rooms.some(other=>other.id===room.id));assert(groupRoom,'Group chat missing.');await api(owner.context.request,'POST','/api/chat/rooms/chat-global/messages',{type:'text',body:'Post-fix global chat'});await api(owner.context.request,'POST',`/api/chat/rooms/${groupRoom.id}/messages`,{type:'text',body:'Post-fix group chat'});const direct=await api(owner.context.request,'POST','/api/chat/direct',{userId:visitor.id});await api(owner.context.request,'POST',`/api/chat/rooms/${direct.roomId}/messages`,{type:'text',body:'Post-fix direct chat'});await api(owner.context.request,'POST',`/api/chat/rooms/${direct.roomId}/messages`,{type:'gif',body:'Post-fix GIF',mediaUrl:gif});const progression=await api(owner.context.request,'GET',`/api/progression/${owner.id}`);assert(progression.profile.totalXp>=70&&progression.earned.length>=1,'XP or achievements missing.');checkpoint(`chat and progression APIs: ${progression.profile.totalXp} XP`);
const hub=await owner.context.newPage();hub.on('pageerror',error=>errors.push(`hub:${error.message}`));await hub.goto(`${base}/hub`,{waitUntil:'networkidle'});await hub.locator('[data-hub-tab="projects"]').click();await hub.getByText('Post-fix platform project',{exact:true}).waitFor({state:'visible'});assert(await hub.locator('#grev-chat-panel').count()===1,'Hub created duplicate chat panels.');assert(await hub.locator('#global-notification-button').count()===1,'Notification launcher missing.');checkpoint('Content Hub UI');
const dashboard=await owner.context.newPage();dashboard.on('pageerror',error=>errors.push(`dashboard:${error.message}`));await dashboard.goto(`${base}/dashboard`,{waitUntil:'networkidle'});assert(await dashboard.locator('#grev-chat-panel').count()===1,'Dashboard created duplicate chat panels.');assert(await dashboard.locator('#global-notification-button').count()===1,'Dashboard created duplicate notification launchers.');await dashboard.locator('#customize-dashboard').click();await dashboard.locator('#dashboard-advanced-tools').waitFor({state:'visible'});for(const selector of ['#dashboard-multi-select','#dashboard-duplicate-tiles','#dashboard-copy-tiles','#dashboard-paste-tiles','#dashboard-layout-versions','[data-dashboard-mode="mobile"]'])assert(await dashboard.locator(selector).count()===1,`${selector} missing.`);await dashboard.locator('#dashboard-cancel-layout').click();await dashboard.locator(`.dashboard-page-tab[data-page-id="${groupPage.id}"]`).click();await dashboard.locator('#customize-dashboard').click();await dashboard.locator('#dashboard-collaborators').click();await dashboard.locator('#dashboard-collaboration-dialog').waitFor({state:'visible'});assert(await dashboard.locator(`#dashboard-collaborator-list [data-user-id="${visitor.id}"]`).count()===1,'Collaborator missing in UI.');await dashboard.locator('[data-collaboration-close]').first().click();await dashboard.locator('#dashboard-cancel-layout').click();await dashboard.locator('#grev-chat-launcher').click();await dashboard.locator('#grev-chat-panel').waitFor({state:'visible'});await dashboard.locator('.grev-chat-room[data-room-id="chat-global"]').click();await dashboard.getByText('Post-fix global chat',{exact:true}).waitFor({state:'visible'});await dashboard.locator('[data-chat-minimise]').click();await dashboard.locator('#grev-chat-dock').waitFor({state:'visible'});await dashboard.locator('#grev-chat-dock').click();await dashboard.locator('#grev-chat-panel').waitFor({state:'visible'});checkpoint('advanced dashboard, collaboration and single minimisable chat UI');
const profile=await owner.context.newPage();profile.on('pageerror',error=>errors.push(`profile:${error.message}`));await profile.goto(`${base}/profile/${owner.id}`,{waitUntil:'networkidle'});await profile.locator('.profile-card-xp .chat-xp').waitFor({state:'visible'});await profile.locator('#profile-achievements').waitFor({state:'visible'});assert(await profile.locator('#profile-achievements .profile-achievement img').count()>=8,'Achievement images missing.');assert(await profile.locator('#profile-functional-modules .profile-functional-module').count()>=2,'Functional profile modules missing.');assert(await profile.locator('#grev-chat-panel').count()===1,'Profile created duplicate chat panels.');const visitorProfile=await owner.context.newPage();visitorProfile.on('pageerror',error=>errors.push(`visitor-profile:${error.message}`));await visitorProfile.goto(`${base}/profile/${visitor.id}`,{waitUntil:'networkidle'});await visitorProfile.locator('#profile-card').click();await visitorProfile.locator('#global-profile-card-popover').waitFor({state:'visible'});await visitorProfile.locator('.global-profile-card-xp .chat-xp').waitFor({state:'visible'});await visitorProfile.locator('.global-profile-card-message-button').click();await visitorProfile.locator('#grev-chat-panel').waitFor({state:'visible'});assert((await visitorProfile.locator('.grev-chat-person-card').textContent()).includes('Postfix visitor'),'Direct chat header profile card is wrong.');checkpoint('profile modules, achievement artwork, XP bars and direct chat UI');assert(errors.length===0,`Browser errors: ${errors.join(' | ')}`);console.log('Post-fix full platform browser verification passed.');}finally{await owner?.context.close();await visitor?.context.close();await browser.close();}})().catch(error=>{console.error(`POSTFIX FAILURE: ${error.stack||error.message||error}`);process.exit(1);});
